/**
 * What kind of file each tracked path is, and whether somebody has ruled on
 * that kind — the other half of `file-size.test.ts`, which asks how long a
 * file is rather than what it is.
 *
 * The ruling itself — that every kind a tree carries has been decided on — is
 * read over a consumer's tree, not this repository's, whose kinds are not the
 * ones the caps were set for.
 */
import { describe, expect, test } from "bun:test";

/**
 * What kind of file a path is, for that ruling: its extension where it has
 * one, its own name where it has none. Read off the name rather than the path,
 * and answered with the whole name rather than an index — the last dot's index
 * over a path made a name carrying no dot report its final character
 * (`Dockerfile` ruling as `e`, joined in silence by every other extensionless
 * name) and a name under a dotted directory report the whole path.
 */
const extension = (path: string) => {
	const name = path.slice(path.lastIndexOf("/") + 1);
	const dot = name.lastIndexOf(".");
	return dot <= 0 ? name : name.slice(dot);
};

describe("what kind of file a path is", () => {
	test.each([
		["src/model.ts", ".ts"],
		[".env.example", ".example"],
		// No dot at all: the name, never its last character.
		["Dockerfile", "Dockerfile"],
		// A dot that opens the name rather than separating an extension.
		[".gitignore", ".gitignore"],
		// The only dot is in a directory: the path is not what is ruled on.
		[".github/workflows/deploy", "deploy"],
	])("%s is ruled as %s", (path, kind) => expect(extension(path)).toBe(kind));
});

bun/file-size.test.ts.source:
/**
 * Fails when a tracked source file is longer than a reader can hold at once:
 * 300 lines of `.ts` or `.tsx`, 200 of `.css`.
 *
 * The check ships as a test rather than a script, the shape
 * `spec-coverage.test.ts` uses: CI already runs `bun test` and so does the
 * pre-push hook, so it is blocking from its first commit with no workflow edit.
 */
import { afterAll, describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, rmSync, symlinkSync, unlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { count, oversize } from "./file-size.ts";

const made: string[] = [];

afterAll(() => {
	for (const dir of made) rmSync(dir, { recursive: true, force: true });
});

const write = (dir: string, files: Record<string, string>) => {
	for (const [path, text] of Object.entries(files)) {
		const full = join(dir, path);
		mkdirSync(dirname(full), { recursive: true });
		writeFileSync(full, text);
	}
};

/** A repository holding `tracked`, and `untracked` left out of the index. */
function fabricate(tracked: Record<string, string>, untracked: Record<string, string> = {}): string {
	const dir = mkdtempSync(join(tmpdir(), "file-size-"));
	made.push(dir);
	const git = (...args: string[]) => {
		const run = Bun.spawnSync(["git", ...args], { cwd: dir });
		if (run.exitCode !== 0) throw new Error(run.stderr.toString());
	};
	git("init", "-b", "main");
	write(dir, tracked);
	git("add", "-A");
	write(dir, untracked);
	return dir;
}

/** `n` lines, newline-terminated. */
const long = (n: number) => `${Array.from({ length: n }, () => "x").join("\n")}\n`;

const paths = (dir: string) => oversize(dir).map((f) => f.path);

// spec: change-slicing/a-file-over-the-cap
describe("a file over the cap", () => {
	test("301 lines of TypeScript fails, naming the file, the count and the cap", () => {
		const dir = fabricate({ "src/a.ts": long(301) });
		expect(oversize(dir)).toEqual([{ path: "src/a.ts", count: 301, cap: 300 }]);
	});

	test("300 lines passes, the bound being inclusive", () => {
		expect(paths(fabricate({ "src/a.ts": long(300) }))).toEqual([]);
	});
});

// spec: change-slicing/a-stylesheet-over-the-cap
describe("a stylesheet over the cap", () => {
	test("201 lines fails", () => {
		const dir = fabricate({ "src/a.css": long(201) });
		expect(oversize(dir)).toEqual([{ path: "src/a.css", count: 201, cap: 200 }]);
	});

	test("200 lines passes", () => {
		expect(paths(fabricate({ "src/a.css": long(200) }))).toEqual([]);
	});
});

// spec: change-slicing/a-test-file-is-not-exempt
describe("what the cap covers", () => {
	test("a test file is not exempt", () => {
		expect(paths(fabricate({ "src/a.test.ts": long(301) }))).toEqual(["src/a.test.ts"]);
	});

	test("a .tsx file is capped like a .ts one", () => {
		expect(paths(fabricate({ "src/a.tsx": long(301) }))).toEqual(["src/a.tsx"]);
	});

	test("a .module.css file is capped at 200 like any stylesheet", () => {
		expect(paths(fabricate({ "src/a.module.css": long(201) }))).toEqual(["src/a.module.css"]);
	});

	test("the cap is chosen by extension, not one number for everything", () => {
		// 250 is over for a stylesheet and under for source, so a single
		// threshold cannot produce this pair.
		const dir = fabricate({ "src/a.css": long(250), "src/b.ts": long(250) });
		expect(paths(dir)).toEqual(["src/a.css"]);
	});

	test.each(["notes.md", "data.json", "config.yml"])("%s is not capped at all, however long", (path) => {
		// A capped file beside it, under its cap: without one the sweep reads
		// nothing and refuses, which would prove the guard rather than this.
		expect(paths(fabricate({ [path]: long(400), "src/a.ts": long(10) }))).toEqual([]);
	});

	test("an extension in capitals is capped all the same", () => {
		// `endsWith` is case-sensitive, so this was capped by nothing.
		expect(paths(fabricate({ "src/A.TS": long(301) }))).toEqual(["src/A.TS"]);
	});

	// spec: change-slicing/an-untracked-file-over-the-cap
	test("an untracked file is out of scope", () => {
		// It is present for its author and absent from a clone, so failing on
		// it would fail one machine and no other.
		const dir = fabricate({ "src/a.ts": long(10) }, { "src/big.ts": long(400) });
		expect(paths(dir)).toEqual([]);
	});
});

describe("counting a line", () => {
	test("a final line with no terminating newline still counts", () => {
		// `wc -l` counts newlines, so it reads this file as 300 and passes it.
		const dir = fabricate({ "src/a.ts": `${long(300).slice(0, -1)}\nx` });
		expect(oversize(dir)).toEqual([{ path: "src/a.ts", count: 301, cap: 300 }]);
	});

	test("a lone carriage return ends a line too", () => {
		// An editor shows a CR-terminated file as separate lines, so a count
		// that saw one line here would pass a file no reader could hold.
		const dir = fabricate({ "src/a.ts": long(301).replaceAll("\n", "\r") });
		expect(oversize(dir)).toEqual([{ path: "src/a.ts", count: 301, cap: 300 }]);
	});

	test("a CRLF ending is one line, not two", () => {
		const dir = fabricate({ "src/a.ts": long(301).replaceAll("\n", "\r\n") });
		expect(oversize(dir)).toEqual([{ path: "src/a.ts", count: 301, cap: 300 }]);
	});

	test.each([
		["", 0],
		["x", 1],
		["x\n", 1],
		["x\ny", 2],
		["x\ny\n", 2],
		["x\r\ny", 2],
		["x\ry\r", 2],
		["\n", 1],
	])("%o counts as %i", (text, n) => expect(count(text as string)).toBe(n));
});

describe("the sweep", () => {
	test("every file over the cap is reported, not only the first", () => {
		// A check stopping at the first turns a backlog into as many rounds as
		// it has files.
		const dir = fabricate({
			"src/a.ts": long(301),
			"src/b.ts": long(302),
			"src/c.css": long(201),
		});
		expect(paths(dir).sort()).toEqual(["src/a.ts", "src/b.ts", "src/c.css"]);
	});

	test("a run that read no files at all fails rather than passing", () => {
		// Every assertion above is over a list, and an empty list satisfies all
		// of them.
		expect(() => oversize(fabricate({ "notes.md": "x\n" }))).toThrow(/no capped files/i);
	});
});

describe("the tree the sweep reads", () => {
	test("a tracked file absent from the work tree is skipped", () => {
		const dir = fabricate({ "src/a.ts": long(10), "src/gone.ts": long(400) });
		unlinkSync(join(dir, "src/gone.ts"));
		expect(paths(dir)).toEqual([]);
	});

	test("a tracked symlink is skipped, however long its target", () => {
		// `lstatSync` reads the link rather than following it, which is the
		// other thing `.isFile()` rejects besides an absent entry.
		const dir = fabricate({ "src/a.ts": long(10), "src/big.txt": long(400) });
		symlinkSync(join(dir, "src/big.txt"), join(dir, "src/link.ts"));
		// Unchecked, a staging failure would leave the link untracked and this
		// case would pass on the tracked file beside it having nothing wrong.
		const staged = Bun.spawnSync(["git", "add", "-A"], { cwd: dir });
		expect(staged.exitCode).toBe(0);
		expect(paths(dir)).toEqual([]);
	});

	test("an empty tracked file counts zero rather than failing to be read", () => {
		expect(paths(fabricate({ "src/a.ts": "", "src/b.ts": long(10) }))).toEqual([]);
	});

	test("run from a subdirectory it still reads the whole repository", () => {
		// `git ls-files` in a subdirectory lists only what is under it and
		// names it relative to it, so a check taking its listing at `cwd`
		// would miss everything above and resolve the rest to nothing.
		const dir = fabricate({ "src/a.ts": long(301), "scripts/b.ts": long(10) });
		expect(paths(join(dir, "scripts"))).toEqual(["src/a.ts"]);
	});
});

bun/file-size.ts.source:
/**
 * The per-file line cap: what a reader has to hold at once to understand one
 * file, as against the diff budget's question of what one change asks them to
 * read.
 *
 * The caps are an enumeration of the extensions they cover rather than of what
 * they exempt, which is the direction `CLAUDE.md` warns against — deliberately,
 * because the numbers differ per extension and a file type nobody has capped is
 * one nobody has measured. Markdown is bounded by the always-on context budget
 * where it matters, and JSON and YAML are read by key rather than by line.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { tracked } from "./tracked.ts";

/** Longest a file of each extension may be, inclusive. */
const CAPS: Record<string, number> = {
	".ts": 300,
	".tsx": 300,
	".css": 200,
};

/**
 * The cap a path is subject to, or `undefined` when it is subject to none.
 * Matched case-insensitively: `endsWith` is not, so `src/A.TS` would be capped
 * by nothing at all — and a cap that silently does not apply is the direction
 * that passes wrongly.
 */
const capOf = (path: string) => {
	const lower = path.toLowerCase();
	return Object.entries(CAPS).find(([ext]) => lower.endsWith(ext))?.[1];
};

/**
 * What ends a line: a CRLF pair, a bare newline, or a bare carriage return.
 * Written once and read two ways, so the alternation cannot drift between the
 * splitting form and the anchored one. A lone `\r` counts because an editor
 * showing a CR-terminated file shows separate lines, and a cap on what a
 * reader holds at once has to agree with what the reader sees.
 */
const ENDING = String.raw`\r\n|\n|\r`;
const ENDINGS = new RegExp(ENDING, "g");
const LAST_ENDING = new RegExp(`(?:${ENDING})$`);

/**
 * Physical lines, blank ones included. A final line carrying no terminating
 * ending counts: `wc -l` counts newline characters and so reads a 301-line
 * file whose last line is unterminated as 300, which is the arithmetic that
 * would let a file over the cap through. A CRLF pair is one ending rather than
 * two, because the alternation tries the pair first.
 */
export function count(text: string): number {
	if (text === "") return 0;
	const endings = text.split(ENDINGS).length - 1;
	return LAST_ENDING.test(text) ? endings : endings + 1;
}

export type Oversize = { path: string; count: number; cap: number };

/**
 * Every tracked file over its cap in the repository containing `cwd`.
 *
 * Tracked only, so a file present for its author and absent from a clone
 * cannot fail one machine and no other.
 */
export function oversize(cwd?: string): Oversize[] {
	const { root, files } = tracked(cwd);

	const found: Oversize[] = [];
	let read = 0;
	for (const path of files) {
		const cap = capOf(path);
		if (cap === undefined) continue;
		read++;
		const lines = count(readFileSync(join(root, path), "utf8"));
		if (lines > cap) found.push({ path, count: lines, cap });
	}

	// A sweep that matched nothing satisfies every assertion made over its
	// result, so it is an error rather than a pass.
	if (read === 0) throw new Error(`no capped files under ${root}`);

	return found;
}
